export default SingleProduct;

SingleProduct.getInitialProps = async (ctx) => {

    const { query } = ctx;
    return WooCommerce.get(`products/${ctx.id}`)
        .then(response => ({ products: response.data }))
        .catch(error => ({ products: error.response.data }));
}